/bin/zsh -lc "rtk python3 - <<'PY'
import json
from pathlib import Path
d=json.loads(Path('.codex-fabric/audit.json').read_text())
for k,v in d.items():
    if k=='history':
        print('history details:')
        for i,h in enumerate(v):
            print(i, sorted(h.keys()))
    elif k in ('diagnostic_checks','checks'):
        print(k, 'count=',len(v))
        if k=='diagnostic_checks': print(json.dumps(v,ensure_ascii=False,sort_keys=True)[:3500])
    else:
        print(k, json.dumps(v,ensure_ascii=False,sort_keys=True)[:900] if isinstance(v,(dict,list)) else repr(v))
PY"
